"""Hidden behavioral tests for jo: nesting. Generated by pbkit from the gold binary."""


def test_brackets_example(run):
    r = run(args=['-p', 'name=Jane', 'point[]=1', 'point[]=2', 'geo[lat]=10', 'geo[lon]=20'])
    assert r.stdout == b'{\n   "name": "Jane",\n   "point": [\n      1,\n      2\n   ],\n   "geo": {\n      "lat": 10,\n      "lon": 20\n   }\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_object_path_example(run):
    r = run(args=['-p', '-d.', 'name=Jane', 'point[]=1', 'point[]=2', 'geo.lat=10', 'geo.lon=20'])
    assert r.stdout == b'{\n   "name": "Jane",\n   "point": [\n      1,\n      2\n   ],\n   "geo": {\n      "lat": 10,\n      "lon": 20\n   }\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_dots_without_d(run):
    r = run(args=['-p', 'name=Jane', 'point[]=1', 'point[]=2', 'geo.lat=10', 'geo.lon=20'])
