def test_harvest_05(run):
    r = run(args=['a[]=1', 'a[]=2', 'geo[lat]=111', 'geo[lon]=222'])
    assert r.stdout == b'{"a":[1,2],"geo":{"lat":111,"lon":222}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_harvest_18_plain(run):
    r = run(args=['a.b=0', 'a.c.d=1', 'a.d.e[]=2', 'a.d.e[]=sam', 'a.c[f]@1', 'b.e[]g=hi'])
    assert r.stdout == b'{"a.b":0,"a.c.d":1,"a.d.e":[2,"sam"],"a.c":{"f":true},"b.e":["hi"]}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_harvest_18_dot(run):
    r = run(args=['-d.', 'a.b=0', 'a.c.d=1', 'a.d.e[]=2', 'a.d.e[]=sam', 'a.c[f]@1', 'b.e[]g=hi'])
    assert r.stdout == b'{"a":{"b":0,"c":{"d":1,"f":true},"d":{"e":[2,"sam"]}},"b":{"e":["hi"]}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_harvest_18_pipe(run):
    r = run(args=['-d|first_char_only', 'a|b=0', 'a|c|d=1', 'a|d|e[]=2', 'a|d|e[]=sam', 'a|c[f]@1', 'b|e[]g=hi'])
    assert r.stdout == b'{"a":{"b":0,"c":{"d":1,"f":true},"d":{"e":[2,"sam"]}},"b":{"e":["hi"]}}\n'
    assert r.stderr == b''
    assert r.returncode == 0


